ont-bold">Estimasi selesai</span><input name="estimated_ready_at" value="{{ old('estimated_ready_at') }}" type="datetime-local" class="w-full rounded-xl border-slate-200 bg-slate-50 px-4 py-3 focus:border-cyan-500 focus:ring-cyan-500"></label></div><div class="rounded-2xl bg-cyan-50 p-5"><div class="flex items-end justify-between"><span class="text-sm font-bold text-cyan-800">Total bayar</span><strong id="totalDisplay" class="text-3xl font-black text-[#10243e]">Rp 0</strong></div><p class="mt-2 text-xs text-cyan-700">Tarif tetap Rp 10.000 / kg. Total final dihitung ulang oleh server.</p></div><div class="flex flex-col gap-3 pt-2 sm:flex-row"><button type="submit" class="flex-1 rounded-xl bg-cyan-500 px-5 py-4 font-black text-white shadow-lg shadow-cyan-500/20 hover:bg-cyan-600">Simpan pesanan</button><button type="button" onclick="sendOrderWhatsApp()" class="flex-1 rounded-xl border-2 border-[#10243e] px-5 py-4 font-black text-[#10243e] hover:bg-slate-50">Kirim via WhatsApp</button></div></form></div></div></div></div>
