@push('scripts')<script>const rate={{ config('laundry.rate') }};const rupiah=new Intl.NumberFormat('id-ID');function calculateTotal(){const weight=Number(document.getElementById('weight').value||0);document.getElementById('totalDisplay').textContent=`Rp ${rupiah.format(Math.ceil(weight*rate))}`;}function sendOrderWhatsApp(){const name=document.querySelector('[name=customer_name]').value.trim();const weight=document.getElementById('weight').value;const total=rupiah.format(Math.ceil(Number(weight||0)*rate));if(!name||!weight){alert('Lengkapi nama dan berat terlebih dahulu.');return;}const text=`Halo Kang Laundry, saya mau order laundry.\nNama: ${name}\nBerat: ${weight} kg\nTotal Bayar: Rp ${total}`;window.open(`https://wa.me/{{ config('laundry.whatsapp_number') }}?text=${encodeURIComponent(text)}`,'_blank');}</script>@endpush
